-- 1. regional_cells (non-US sub-national rows)
UPDATE regional_cells
SET cost_stack = jsonb_build_object(
  'rent_occupancy',         ROUND(rev_p50 * 0.07),
  'payroll_total',          ROUND(rev_p50 * 0.25),
  'cost_of_goods_sold',     ROUND(rev_p50 * 0.35),
  'utilities',              ROUND(rev_p50 * 0.03),
  'marketing_acquisition',  ROUND(rev_p50 * 0.03),
  'insurance_professional', ROUND(rev_p50 * 0.05),
  'equipment_maintenance',  ROUND(rev_p50 * 0.04),
  'regulatory_licensing',   ROUND(rev_p50 * 0.02),
  'refreshed_at',           '2026-05-24',
  'source_note',            'Auto repair industry benchmarks 2024 (Sharpsheets 3,300+ businesses). Country revenue captures local price level implicitly.',
  'grade',                  'C'
)
WHERE industry_id = 'auto_repair_shops'
  AND rev_p50 IS NOT NULL
  AND rev_p50 > 0
  AND (cost_stack IS NULL OR cost_stack->>'grade' IN ('C', 'D'));

